import Redis from 'ioredis';

// Connect via Sentinel — automatically follows failovers
const redis = new Redis({
  sentinels: [
    { host: '127.0.0.1', port: 26379 },
    { host: '127.0.0.1', port: 26380 },
    { host: '127.0.0.1', port: 26381 },
  ],
  name: 'mymaster',    // must match 'sentinel monitor <name>'
  role: 'master',      // 'master' for writes, 'slave' for reads
});

// The client asks Sentinel for the current primary address
// and reconnects automatically after failover
await redis.set('key', 'value');
